-- 170: Ontario PHIPA as a compliance framework.
-- The Personal Health Information Protection Act, 2004 (S.O. 2004, c. 3, Sched. A) is
-- Ontario's health privacy statute and the usual Canadian reference point for health
-- information (the federal government has declared it substantially similar to PIPEDA
-- for health information custodians). 52 requirements in 8 domains, each phrased
-- as an assessment question with supporting evidence, and ending with a "Source" line
-- naming the section of the Act or of its General regulation (O. Reg. 329/04). Where a
-- section bundles several obligations Bayanis splits it (PHIPA.s12-1, -2, ...); that
-- sub-numbering is Bayanis's, not the Act's, and the Source line says so. Sections are
-- cited at section level only. Stored the same way as PIPEDA and Québec Law 25
-- (COMPLIANCE_ONLY, one "Requirement" level, the standard status list), with the
-- regulation details (db/162) and its Regulatory registry entry (db/163).
-- Generated from one requirement list; written from the author's knowledge of the Act,
-- not copied from the statute — to be verified by a privacy professional before use.
-- Safe to run more than once.

BEGIN;

INSERT INTO bayanat.gov_compliance_frameworks
  (name, code, version, description, regulation_group_code, is_applicable_indicator, assessment_mode,
   region_name, countries_in_scope, scope_note, regulatory_body, effective_date, effective_date_note, official_url, reference_links)
VALUES (
  'Ontario PHIPA', 'ON_PHIPA', '2004, amended 2020',
  $t$Ontario — Personal Health Information Protection Act, 2004 (S.O. 2004, c. 3, Sched. A). Sets the rules for collecting, using and disclosing personal health information by health information custodians in Ontario, their agents, and those who receive personal health information from a custodian. Overseen by the Information and Privacy Commissioner of Ontario (IPC). Offences carry fines of up to CA$200,000 for individuals and CA$1,000,000 for organizations; since 1 January 2024 the IPC can also impose administrative monetary penalties of up to CA$50,000 for individuals and CA$500,000 for organizations.$t$,
  'INTERNATIONAL_STANDARDS', true, 'COMPLIANCE_ONLY',
  'North America', 'Canada (Ontario)',
  $t$Health information custodians in Ontario (health care practitioners, hospitals, long-term care homes, pharmacies, laboratories, ambulance services and others listed in the Act), their agents, and persons who receive personal health information from a custodian. The rules on health numbers apply to everyone.$t$,
  'Information and Privacy Commissioner of Ontario (IPC)', DATE '2004-11-01',
  $t$In force since 1 November 2004. Amended several times since, notably in 2016 (mandatory breach notification, in effect 2017) and 2020 (higher fines, electronic audit logs, administrative monetary penalties — the penalties in effect 1 January 2024).$t$,
  'https://www.ontario.ca/laws/statute/04p03',
  $t$[{"url": "https://www.ontario.ca/laws/regulation/040329", "label": "O. Reg. 329/04 (General)"}, {"url": "https://www.ipc.on.ca", "label": "Information and Privacy Commissioner of Ontario"}]$t$::jsonb
)
ON CONFLICT (code) DO NOTHING;

